/* Four-step journey as tabs: Scan → Confirm → Take → Refill (the screens are still Returnly's Item, Return and Get paid cards until the next steps change them). Each screen asks for one thing; discharge-paper reading fills in each medication. */
const renderBeforeJourney=render,exampleBeforeJourney=exampleOrder;
let journey={step:'capture',preview:'',receipt:'',error:'',pages:[],purchaseId:'',more:false,reading:false,mode:'papers',shots:[],shotFrom:''},cameraStream=null,cameraAttempted=false,cameraToken=0,planTab=null;
const blankProduct=()=>({name:'',price:'',category:'box',demo:false,intent:'keep'});
const flowSteps=['Scan','Confirm','Take','Refill'];
function flowShell(title,description,body,step,plan=null){const tabs=flowSteps.map((name,n)=>{const k=n+1,done=plan&&k>=3?(k===3?plan.sent:plan.received):k<step,state=k===step?' current':done?' done':'',label=(done?'✓ ':'')+name,current=k===step?' aria-current="step"':'';return plan&&!plan.kept&&k>=3?`<button type="button" class="flow-tab${state}" data-plan-tab="${k===3?'return':'paid'}"${current}>${label}</button>`:`<span class="flow-tab${state}"${current}>${label}</span>`}).join('');return `<section class="guided-flow"><div class="guided-top"><button id="flow-back" aria-label="Go back">← Back</button></div><nav class="flow-tabs" aria-label="Care steps">${tabs}</nav>${title?`<h1>${title}</h1>`:''}${description?`<p class="intro">${description}</p>`:''}${body}<p class="flow-status" role="alert">${esc(journey.error)}</p></section>`}
function stopJourneyCamera(){cameraToken++;if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}
/* The Scan page's camera stays on between shots: the bottle's 3 label photos, then the card's photo. */
const cameraStep=()=>journey.step==='capture'||journey.step==='cardPhoto';
async function startJourneyCamera(force=false){const video=$('#flow-video');if(!video)return;if(cameraStream){video.srcObject=cameraStream;video.play?.().catch(()=>{});const m=$('#camera-message'),b=$('#flow-shutter');if(m)m.hidden=true;if(b)b.disabled=journey.reading;return}if(cameraAttempted&&!force)return;cameraAttempted=true;const token=++cameraToken;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Unavailable');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(token!==cameraToken||view!=='upload'||!cameraStep()){stream.getTracks().forEach(t=>t.stop());return}cameraStream=stream;video.srcObject=stream;await video.play();$('#camera-message').hidden=true;$('#flow-shutter').disabled=false}catch{if(token===cameraToken&&$('#camera-message'))$('#camera-message').textContent='Camera unavailable. Upload the papers to continue.'}}
/* Step 1: scan. */
uploadPage=function(){if(journey.mode==='bottles')return bottleScanPage();return flowShell('','','<div class="camera-shell"><h1>Scan the discharge papers.</h1><p>Take a photo of each page, or upload the PDF.</p><div class="camera-window"><video id="flow-video" autoplay muted playsinline aria-label="Discharge papers camera preview"></video><div class="frame"></div><div class="camera-message" id="camera-message">Allow camera access, or upload the papers.</div></div><div class="capture-controls"><label for="flow-receipt" tabindex="0" role="button" aria-label="Upload discharge papers">'+icon('grid')+'Upload</label><button class="shutter" id="flow-shutter" disabled aria-label="Take a photo of this page"></button><button id="flow-camera-start">'+icon('spark')+'Retry camera</button></div><input id="flow-receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple></div><button class="flow-secondary" id="flow-demo">Try an example instead</button><button class="flow-secondary" id="flow-bottles">No discharge papers? Start with the bottles</button><p class="flow-subtle">Your discharge papers are saved privately to your account.</p>',1)};
function retainReview(){const f=$('#flow-item-form');if(!f)return;const el=f.elements;if(el.retailer)draft.retailer=el.retailer.value;if(el.purchased)draft.purchased=el.purchased.value;draft.products.forEach((p,n)=>{if(el['name-'+n])p.name=el['name-'+n].value.replace(/\s+/g,' ');if(el['price-'+n])p.price=el['price-'+n].value;if(el['how-'+n])p.instructions=el['how-'+n].value.trim();if(el['doctor-'+n])p.prescriber={...(p.prescriber||{}),name:el['doctor-'+n].value.trim()};if(el['doctor-phone-'+n])p.prescriber={...(p.prescriber||{}),phone:el['doctor-phone-'+n].value.trim()};if(el['pharmacy-'+n])p.pharmacy={...(p.pharmacy||{}),name:el['pharmacy-'+n].value.trim()};if(el['pharmacy-phone-'+n])p.pharmacy={...(p.pharmacy||{}),phone:el['pharmacy-phone-'+n].value.trim()};if(el['checked-'+n])p.checked=!!el['checked-'+n].checked})}
/* "Try an example": made-up discharge papers for a fictional patient, so the Confirm card can be tried without real papers. */
const EXAMPLE_DOCTOR={name:'Dr. Maya Patel',phone:'(555) 201-3344'},EXAMPLE_PHARMACY={name:'Main Street Pharmacy',address:'12 Main St',phone:'(555) 300-1200'};
function exampleDischarge(){draft={channel:'store',evidence:['Example discharge papers'],retailer:'',purchased:today(),delivered:'',discharge:{hospital:'Example Hospital',discharged:today(),appointments:[],warningSigns:[],contacts:[]},products:[['Lisinopril 10 mg','Take 1 tablet by mouth every morning.'],['Metoprolol 25 mg','Take 1 tablet by mouth twice a day.'],['Acetaminophen 500 mg','Take 2 tablets every 6 hours as needed for pain. Do not take more than 8 tablets in 24 hours.']].map(([name,instructions])=>({...blankProduct(),name,instructions,prescriber:EXAMPLE_DOCTOR,pharmacy:EXAMPLE_PHARMACY,photoKey:'medication',demo:true,intent:'keep'}))}}
/* Bottle photos: up to 3, because the label wraps around the bottle. They're read together as one label and checked against
   the papers. A difference is never settled by the app: the family calls the pharmacy and says which one they were told to follow. */
const MAX_BOTTLE_PHOTOS=3,LABEL_FAILED={unavailable:'Reading labels isn’t available right now. Check the bottle yourself.',failed:'We couldn’t read this label. Take another photo of the side with the directions.',limit:'You’ve read a lot of labels this hour. Check the bottle yourself.'};
function bottleRow(p,n){const count=(p.labelPhotos||[]).length;if(p.noBottle)return `<p class="flow-note">No bottle yet: this becomes a “Pick up from the pharmacy” task. <button type="button" class="flow-text-link" data-flow-nobottle="${n}">I have the bottle</button></p>`;const next=BOTTLE_SHOTS[count];return `<p class="pick-price plan-when bottle-line"><span>${p.labelReading?'Reading the label…':count?`${count} of ${MAX_BOTTLE_PHOTOS} photos${next?` · Next: ${next[0].toLowerCase()}, ${next[1].toLowerCase()}`:''}`:'Photo 1: the front, with the name and directions'}</span>${count&&count<MAX_BOTTLE_PHOTOS?`<label class="flow-text-link" for="flow-photo-${n}" tabindex="0" role="button">Add another photo</label>`:''}${count?'':`<button type="button" class="flow-text-link" data-flow-nobottle="${n}">No bottle yet</button>`}</p>${count<MAX_BOTTLE_PHOTOS&&!p.labelReading?bottleGuide(count):''}${p.labelNote?`<p class="flow-note">${esc(p.labelNote)}</p>`:''}`}
/* Example shots, so nobody has to guess what to photograph: drawn bottles with a made-up label (never a real patient's),
   the part that matters outlined. The next shot to take is marked, and the ones already taken are ticked. */
const BOTTLE_SHOTS=[['Front','Name and directions',['LISINOPRIL','10 MG TABLET','','Take 1 tablet','by mouth','every day'],[0,5]],['Turn it','Pharmacy, refills, doctor',['MAIN ST PHARMACY','TEL 555-0100','QTY 30','REFILLS 2','DR M. PATEL','Pink round tablet'],[0,5]],['Turn again','Warnings',['IMPORTANT','INFORMATION','May cause','dizziness.','Take exactly','as directed.'],[0,5]]];
function bottleSVG([,,lines,[from,to]]){const y=n=>62+n*11;return `<svg viewBox="0 0 100 150" role="img" aria-hidden="true" class="bottle-svg"><rect x="18" y="8" width="64" height="22" rx="5" fill="#fff" stroke="#bbb"/><rect x="22" y="28" width="56" height="116" rx="8" fill="#e3a14a"/><rect x="24" y="50" width="52" height="80" rx="3" fill="#fff"/>${lines.map((t,n)=>`<text x="50" y="${y(n)}" text-anchor="middle" font-size="${n<2?6.4:5.6}" font-weight="${n<2?700:400}" fill="#111" font-family="Arial,sans-serif">${esc(t)}</text>`).join('')}<rect x="25.5" y="${y(from)-8}" width="49" height="${(to-from)*11+12}" rx="3" fill="none" stroke="#d33" stroke-width="1.4" stroke-dasharray="3 2"/></svg>`}
function bottleGuide(count,open=!count){return `<details class="pick-edit"${open?' open':''}><summary>Which photos?</summary><div class="bottle-guide">${BOTTLE_SHOTS.map((shot,n)=>`<figure class="${n===count?'is-next':''}">${bottleSVG(shot)}<figcaption><b>${n<count?'✓ ':''}${n+1}. ${esc(shot[0])}</b><br>${esc(shot[1])}</figcaption></figure>`).join('')}</div><p class="pick-price">Fill the screen with the label, in good light, with no glare. Turn the bottle a little between photos so the whole label shows. Example label, not a real prescription.</p></details>`}
/* No discharge papers: the same Scan page, for the bottle. The 3 label photos are taken (or uploaded) one after another with
   the example for each, then read together as one label. When the label is read, the card fills itself in: a camera scan
   then asks for 1 clear photo for the card; uploaded photos use the one with the name and directions. Only what couldn't
   be read is left to type in. */
const cameraBlock=(label,upload,accept,multiple)=>`<div class="camera-window"><video id="flow-video" autoplay muted playsinline aria-label="${label} camera preview"></video><div class="frame"></div><div class="camera-message" id="camera-message">Allow camera access, or upload the photos.</div></div><div class="capture-controls"><label for="${upload}" tabindex="0" role="button" aria-label="Upload photos">${icon('grid')}Upload</label><button class="shutter" id="flow-shutter" disabled aria-label="Take this photo"></button><button id="flow-camera-start">${icon('spark')}Retry camera</button></div><input id="${upload}" type="file" accept="${accept}"${multiple?' multiple':''}>`;
function bottleScanPage(){if(journey.step==='cardPhoto')return flowShell('','',`<div class="camera-shell"><h1>One photo for the card.</h1><p>We read the label. Now take a clear photo of the bottle, so everyone knows the exact medication.</p>${cameraBlock('Medication','flow-card-upload','image/*',false)}</div><button class="flow-secondary" id="flow-card-skip">Use the front label photo</button>`,1);const n=journey.shots.length,shot=BOTTLE_SHOTS[Math.min(n,MAX_BOTTLE_PHOTOS-1)];return flowShell('','',`<div class="camera-shell"><h1>Scan the medication bottle.</h1><p><b>Photo ${n+1} of ${MAX_BOTTLE_PHOTOS}:</b> ${esc(shot[0].toLowerCase())}, ${esc(shot[1].toLowerCase())}. Or upload all ${MAX_BOTTLE_PHOTOS} photos.</p>${cameraBlock('Medication bottle','flow-bottle-upload','image/*',true)}</div>${bottleGuide(n,true)}${n?`<button class="flow-secondary" id="flow-bottle-read">Read ${n===1?'this photo':`these ${n} photos`} now</button>`:''}<button class="flow-secondary" id="flow-papers">I have the discharge papers</button><p class="flow-subtle">The photos are saved privately to your account.</p>`,1)}
function startBottles(){stopJourneyCamera();cameraAttempted=false;Object.assign(journey,{mode:'bottles',step:'capture',shots:[],shotFrom:'',error:'',more:false,purchaseId:''});view='upload';render();window.scrollTo(0,0)}
async function addBottleShots(urls,from){if(!journey.shotFrom)journey.shotFrom=from;journey.shots=[...journey.shots,...urls].slice(0,MAX_BOTTLE_PHOTOS);journey.error='';if(journey.shots.length>=MAX_BOTTLE_PHOTOS)return readBottleShots();render()}
async function readBottleShots(){const shots=journey.shots;if(!shots.length||journey.reading)return;readingState(true,'Reading the label…');let r={};try{const res=await fetch('/api/label/read',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({photos:shots,med:null})});r=await res.json().catch(()=>({}));if(!res.ok)throw Error(r.error||LABEL_FAILED.failed)}catch(err){readingState(false);journey.error=err.message;render();return}readingState(false);
const p={...blankProduct(),labelPhotos:shots},l=r.label;if(draft.bottlesOnly&&draft.products.some(x=>x.name))draft.products.push(p);else draft={channel:'store',evidence:[],products:[p],retailer:'',purchased:today(),delivered:'',discharge:null,bottlesOnly:true};if(l)applyLabel(p,l,[]);else p.labelNote=LABEL_FAILED[r.reason]||LABEL_FAILED.failed;p.scanned=!!(l&&(p.name||p.instructions));p.photo=shots[l&&l.mainPhoto!=null&&shots[l.mainPhoto]?l.mainPhoto:0];
if(p.scanned&&journey.shotFrom==='camera'){journey.step='cardPhoto';render();return}finishBottleScan()}
function finishBottleScan(photo){const p=draft.products[draft.products.length-1];if(photo)p.photo=photo;stopJourneyCamera();journey.mode='papers';journey.shots=[];journey.shotFrom='';const missing=[!p.name&&'the name',!howText(p)&&'how to take it'].filter(Boolean);openReview(!p.label?p.labelNote+' Type it in from the bottle.':missing.length?`We couldn’t read ${missing.join(' or ')}. Type ${missing.length>1?'them':'it'} in from the bottle.`:'We read the label. Check it against the bottle, pick the times, then confirm.')}
/* On a card filled from the bottle, what was read shows as text with "Fix a mistake"; only blank fields are typed in. */
const readField=(p,v)=>p.scanned&&!p.fixing&&v;
function nameField(p,n){return readField(p,p.name)?`<p class="pick-name">${esc(p.name)}</p><input type="hidden" name="name-${n}" value="${esc(p.name)}">`:`<textarea class="pick-name" name="name-${n}" aria-label="Medication ${n+1} name" required maxlength="100" rows="2" placeholder="Medication name">${esc(p.name)}</textarea>`}
function howField(p,n){const how=howText(p);return readField(p,how)?`<p class="pick-price">${esc(how)}</p><input type="hidden" name="how-${n}" value="${esc(how)}"><button type="button" class="flow-text-link" data-flow-fix="${n}">Fix a mistake</button>`:`<textarea class="pick-name pick-how" name="how-${n}" aria-label="How to take medication ${n+1}, as written on the papers" maxlength="600" rows="3" placeholder="How to take it, as written on the ${draft.bottlesOnly?'bottle':'papers'}">${esc(how)}</textarea>`}
const CHECK_MARK={true:'✓ Matches',false:'⚠ Different',null:'Check it yourself'};
function checkRows(p,n){if(p.label&&(!p.check||!p.check.length))return `<div class="flow-note"><p><b>From the bottle label.</b> Check each line against the bottle in your hand.</p>${p.pillLooks?`<p><b>Looks like</b> · ${esc(p.pillLooks)}</p>`:''}</div>`;if(!p.check||!p.check.length)return '';const differs=p.check.some(r=>r.match===false);return `<div class="flow-note">${p.check.map(r=>`<p><b>${esc(r.field)}</b> · ${CHECK_MARK[r.match]}${r.match===false||r.match===null?`<br>Papers: ${esc(r.papers||'not on the papers')}<br>Bottle: ${esc(r.bottle||'not on the label')}`:''}</p>`).join('')}${p.pillLooks?`<p><b>Looks like</b> · ${esc(p.pillLooks)}</p>`:''}${differs?`<p><b>The papers and the bottle don’t match.</b> Call the pharmacy before giving this medication.</p>${p.pharmacy&&p.pharmacy.phone?`<a class="flow-text-link" href="tel:${esc(p.pharmacy.phone.replace(/[^\d+]/g,''))}">Call ${esc(p.pharmacy.name||'the pharmacy')} ${esc(p.pharmacy.phone)}</a>`:''}${p.follow?`<p>You were told to follow the ${p.follow==='bottle'?'bottle':'papers'}.</p>`:`<button type="button" class="flow-text-link" data-flow-follow="papers" data-n="${n}">They told me to follow the papers</button><button type="button" class="flow-text-link" data-flow-follow="bottle" data-n="${n}">They told me to follow the bottle</button>`}`:''}</div>`}
async function readLabel(n){const p=draft.products[n];if(!p||!(p.labelPhotos||[]).length)return;p.labelReading=true;p.labelNote='';render();let r={};try{const res=await fetch('/api/label/read',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({photos:p.labelPhotos,med:draft.bottlesOnly||!draft.discharge?null:{name:p.name||'',instructions:p.instructions||'',dose:p.dose||'',route:p.route||'',frequency:p.frequency||''}})});r=await res.json().catch(()=>({}));if(!res.ok)throw Error(r.error||LABEL_FAILED.failed)}catch(err){p.labelReading=false;p.labelNote=err.message;render();return}p.labelReading=false;if(!r.label){p.labelNote=LABEL_FAILED[r.reason]||LABEL_FAILED.failed;render();return}applyLabel(p,r.label,r.check);render()}
/* What the label adds to the card: only fills what the papers left empty, and keeps the label's own facts for Take and Refill. */
function applyLabel(p,l,check){p.label=l;p.check=check||[];p.follow='';p.labelNote=l.note||'';if(!p.name&&l.name)p.name=[l.name,l.strength].filter(Boolean).join(' ');if(!p.instructions&&!p.dose&&l.directions)p.instructions=l.directions;if(!(p.pharmacy&&p.pharmacy.name)&&l.pharmacy&&(l.pharmacy.name||l.pharmacy.phone))p.pharmacy=l.pharmacy;else if(p.pharmacy&&!p.pharmacy.phone&&l.pharmacy&&l.pharmacy.phone)p.pharmacy={...p.pharmacy,phone:l.pharmacy.phone};if(!(p.prescriber&&p.prescriber.name)&&l.prescriber)p.prescriber={...(p.prescriber||{}),name:l.prescriber};Object.assign(p,{pillLooks:l.pillLooks||'',quantity:l.quantity,refills:l.refills,refillBy:l.refillBy||'',filled:l.filled||'',discardAfter:l.discardAfter||'',warnings:l.warnings||[]})}
/* Step 2: the Confirm card, one per medication, in the Item card's shape: the bottle's photo, the name, how to take it as written
   on the papers, and the doctor and pharmacy in one collapsed row. Confirm turns its reminders on. */
const howText=p=>p.instructions||[p.dose,p.route,p.frequency,p.duration].filter(Boolean).join(', ');
/* Dose times: the family picks them from the 4 slots printed on most labels. How many comes from the directions ("twice a day"
   is 2), never more; "as needed" gets none, so no timed reminder. Exact times printed on the papers are used as they are, and
   a slot is only filled in for them when the directions name it ("every morning"). The app never guesses a time. */
const SLOTS=[['Morning','08:00'],['Midday','12:00'],['Evening','18:00'],['Bedtime','21:00']];
const slotName=t=>(SLOTS.find(s=>s[1]===t)||[''])[0];
const clockText=t=>doseTime('2000-01-01T'+t);
function dosesPerDay(p){const w=(howText(p)||'').toLowerCase();if(!w)return null;if(/\b(as needed|if needed|when needed|prn)\b/.test(w))return 0;const every=w.match(/every (\d+) hours?/);if(every)return {6:4,8:3,12:2,24:1}[every[1]]??null;if(/\b(four|4) times (a|per|each) day\b|\bqid\b/.test(w))return 4;if(/\b(three|3) times (a|per|each) day\b|\btid\b/.test(w))return 3;if(/\b(twice|two times|2 times) (a|per|each) day\b|\bbid\b/.test(w))return 2;if(/\b(once (a|per|each) day|every day|each day|daily|every (morning|evening|night)|at bedtime|qd)\b/.test(w))return 1;return null}
const printedTimes=p=>!p.slots&&(p.times||[]).length>0;
function namedSlot(p){if(dosesPerDay(p)!==1)return null;const w=howText(p).toLowerCase();return /\bmorning\b/.test(w)?'08:00':/\b(bedtime|at night)\b/.test(w)?'21:00':/\bevening\b/.test(w)?'18:00':/\b(noon|midday|lunch)\b/.test(w)?'12:00':null}
function slotRow(p,n){if(printedTimes(p))return `<p class="pick-price plan-when"><span>Times</span>${esc(p.times.map(clockText).join(', '))}, as printed on the papers</p>`;const need=dosesPerDay(p);if(need===0)return '<p class="flow-note">Only when needed, so there’s no timed reminder. Never more than the label says.</p>';if(!p.slots){const named=namedSlot(p);if(named)p.slots=[named]}const on=p.slots||[],full=!!need&&on.length>=need;return `<div class="slot-row"><p class="pick-price">${need?`When will you give it? Pick ${need===1?'1 time':need+' times'}.`:'When will you give it?'}</p><div class="slot-picks">${SLOTS.map(([name,time])=>{const sel=on.includes(time);return `<button type="button" class="pick-toggle slot" data-flow-slot="${time}" data-n="${n}" aria-pressed="${sel}"${!sel&&full?' disabled':''}>${sel?'✓ ':''}${name}<small>${clockText(time)}</small></button>`}).join('')}</div></div>`}
function slotProblem(p){if(printedTimes(p))return '';const need=dosesPerDay(p),on=(p.slots||[]).length;if(need===0)return '';if(need&&on!==need)return `pick ${need===1?'the time':need+' times'} you’ll give it`;if(!on)return 'pick when you’ll give it';return ''}
reviewPage=function(){if(!draft.products.length)draft.products.push(blankProduct());const many=draft.products.length>1,picked=draft.products.filter(p=>p.intent==='return').length;return flowShell('','',`<form id="flow-item-form" class="guided-form pick-form" novalidate><ul class="pick-grid${many?'':' single'}">${draft.products.map((p,n)=>`<li class="pick-card${p.intent==='return'?' is-return':''}"><label class="pick-photo" for="flow-photo-${n}" tabindex="0" role="button" aria-label="${p.photo?'Change':'Add'} photo of medication ${n+1}">${photo(p)}${p.photo?'':'<span class="pick-photo-hint">+ Photos of the bottle</span>'}</label><input type="file" id="flow-photo-${n}" data-flow-photo="${n}" accept="image/*" hidden>${bottleRow(p,n)}${nameField(p,n)}${howField(p,n)}<details class="pick-edit"><summary>Doctor and pharmacy</summary><label class="pick-price plan-when"><span>Doctor</span><input name="doctor-${n}" aria-label="Doctor who prescribed medication ${n+1}" maxlength="80" value="${esc(p.prescriber?.name||'')}" placeholder="Name"></label><label class="pick-price plan-when"><span>Phone</span><input name="doctor-phone-${n}" type="tel" aria-label="Doctor's phone for medication ${n+1}" maxlength="30" value="${esc(p.prescriber?.phone||'')}" placeholder="For refills"></label><label class="pick-price plan-when"><span>Pharmacy</span><input name="pharmacy-${n}" aria-label="Pharmacy for medication ${n+1}" maxlength="100" value="${esc(p.pharmacy?.name||'')}" placeholder="Name"></label><label class="pick-price plan-when"><span>Phone</span><input name="pharmacy-phone-${n}" type="tel" aria-label="Pharmacy's phone for medication ${n+1}" maxlength="30" value="${esc(p.pharmacy?.phone||'')}" placeholder="Pharmacy phone"></label></details>${checkRows(p,n)}${slotRow(p,n)}<label class="packing-row"><input type="checkbox" name="checked-${n}"${p.checked?' checked':''}>${draft.bottlesOnly?'I checked this against the bottle.':'I checked this against the papers and the bottle.'}</label>${many?`<button type="button" class="pick-toggle" data-flow-choice="${n}" aria-pressed="${p.intent==='return'}">${p.intent==='return'?'✓ Confirmed':'Confirm'}</button>`:'<button class="pick-toggle" data-flow-return>Confirm</button>'}</li>`).join('')}</ul><button type="button" class="flow-secondary" data-flow-another>Add another medication</button>${many&&picked?`<div class="pick-cta"><button class="primary">Continue</button></div>`:''}</form>`,2)};
showAdd=function(){stopJourneyCamera();cameraAttempted=false;journey={step:'capture',preview:'',receipt:'',error:'',pages:[],purchaseId:'',more:false,reading:false,mode:'papers',shots:[],shotFrom:''};view='upload';render();window.scrollTo(0,0)};
showDetail=function(id){if(!find(id))return;selected=id;planTab=null;journey.error='';view='plan';render();window.scrollTo(0,0)};
/* Steps 3 and 4 share one screen with two tabs. Each tab is one card in the same shape as the Item card: photo, item, one fact, one button. */
const NO_STORE='Store not added';
function planCard(i,fact,action,tag='div',attrs='',rows=''){return `<${tag} class="pick-grid single plan-grid${rows?' guided-form':''}"${attrs}><div class="pick-card plan-card"><div class="pick-photo">${photo(i)}</div><strong class="plan-name">${esc(i.name)}</strong>${rows||`<small class="plan-meta">${esc(i.retailer)}<span> · ${money(i.price)}</span></small><div class="plan-fact">${fact}</div>`}${action}</div></${tag}>`}
/* Steps 3 and 4 for a medication: Take (how to take it as written, the doctor and the pharmacy, and today's dose) and Refill.
   A skipped dose is only recorded: it is never moved, doubled or made up. Anything medical points to the doctor or pharmacist. */
