let policyRun=0;const policyTokens={},lookupTimers={},lookupTries={};
/* A store we don't have is looked up on the server in the background; ask again a few times until the answer is in. */
function lookupWait(i,state){if(state!=='pending'){delete lookupTries[i.id];return}const n=lookupTries[i.id]=(lookupTries[i.id]||0)+1;if(n>6)return;lookupTimers[i.id]=setTimeout(()=>{const live=find(i.id);if(live)checkPolicy(live)},15000*n)}
function policyRows(i){if(i.demo||!i.policyLine||i.policyStore!==i.retailer)return '';const a=i.conditionAnswers||{};return (i.policyQuestions||[]).map(q=>`<label class="pick-price plan-when"><span>${esc(q.label)}</span><select data-policy-answer="${esc(q.id)}" aria-label="${esc(q.label)}"><option value="">Choose</option><option value="yes"${a[q.id]===true?' selected':''}>Yes</option><option value="no"${a[q.id]===false?' selected':''}>No</option></select></label>`).join('')+`<small class="plan-meta">${i.policyUnverified?'Unverified: found on the store’s site, not checked by Adltrack yet.<br>':''}${esc(i.policyLine)}</small>`+reportRow(i)}
