document.addEventListener('click',async e=>{const b=e.target.closest('[data-report-open],[data-report-send]');if(!b||view!=='plan')return;e.preventDefault();const i=find(selected);if(!i)return;if(b.hasAttribute('data-report-open')){reportOpen=i.id;render();$('[data-report-note]')?.focus();return}if(!b.hasAttribute('data-report-send'))return;if(b.getAttribute('aria-disabled')==='true')return;const note=$('[data-report-note]')?.value||'';b.setAttribute('aria-disabled','true');try{await Account.api('POST','/api/policy/report',{retailerId:i.retailerId||'',store:i.retailer,itemName:i.name,policyVersion:i.policyVersion||null,policyLine:i.policyLine||'',note});reportOpen='';render();toast('Thanks. We’ll review it.')}catch(err){b.removeAttribute('aria-disabled');journey.error=err.message;render()}});
async function checkPolicy(i){if(!i||i.demo||!i.retailer||i.retailer===NO_STORE)return;const token=policyTokens[i.id]=++policyRun,store=i.retailer;if(lookupTimers[i.id])clearTimeout(lookupTimers[i.id]);try{const r=await fetch('/api/policy',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({item:{name:i.name,retailer:store,purchased:i.purchased,delivered:i.delivered,channel:i.channel,dateSet:!!i.dateSet,receiptPolicy:i.receiptPolicy||'',orderNumber:i.orderNumber||''},answers:i.conditionAnswers||{},retailerId:i.retailerId,category:i.policyCategory})});if(!r.ok)return;const {retailer,category,result,guide,lookup}=await r.json(),live=find(i.id);if(!live||policyTokens[i.id]!==token||live.retailer!==store)return;lookupWait(live,lookup);Object.assign(live,result.fields,{retailerId:retailer?retailer.id:'',policyChecked:retailer?retailer.checked:'',policyVersion:retailer?retailer.version:0,policyCategory:category||'',returnable:result.returnable,returnableReason:result.reason,holidayReturnBy:result.holiday?result.holiday.returnBy:'',policyFacts:result.facts,policyQuestions:result.questions,policyLine:result.line,policyUnverified:!!(retailer&&retailer.unverified),policyLookup:lookup||'',policyStore:store,returnGuide:guide||null});save();if(view==='plan'&&selected===live.id||['overview','calendar','wallet','reminders'].includes(view))render()}catch{}}
document.addEventListener('change',e=>{const q=e.target.dataset?.policyAnswer;if(!q)return;const i=find(selected);if(!i)return;const a={...(i.conditionAnswers||{})};if(e.target.value)a[q]=e.target.value==='yes';else delete a[q];i.conditionAnswers=a;save();checkPolicy(i)});
