function wayHTML(m){return `<strong>${esc(m.label)}</strong>${m.cost?` · ${esc(m.cost)}`:''}<ol>${m.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${m.needs?`<p>${esc(m.needs)}</p>`:''}${m.note?`<p>${esc(m.note)}</p>`:''}`}
