function nearbyHTML(i,m,what='drop-offs'){const key=i.id+'#'+m.index;if(nearby.key!==key||!nearby.state)return '';if(nearby.state==='loading')return `<p>Finding ${what} near you…</p>`;if(nearby.state==='error')return `<p>${esc(nearby.note)}</p>`;return nearby.places.map(p=>`<p><strong>${esc(p.name)}</strong> · ${p.miles} mi${p.openNow===true?' · Open now':p.openNow===false?' · Closed now':''}${p.address?`<br>${esc(p.address)}`:''}${todayHours(p)?`<br>Today: ${esc(todayHours(p))}`:''}<br><a class="flow-text-link" href="${esc(p.directions)}" target="_blank" rel="noopener">Directions ↗</a></p>`).join('')}
